    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'M1', 'Missie', 'Gezond ouder worden door gezamenlijk lichamelijk en geestelijk te blijven bewegen', 'De missie van het verzorgingshuis: bewoners zo lang en zo prettig mogelijk vitaal houden, samen — niet alleen door beweging, maar ook door sociale verbondenheid en geestelijke activiteit. Dit vormt het hoogste anker van de doelenboom: alle onderliggende doelen, benefits en programmabaten moeten hier aantoonbaar aan bijdragen.', '', '-', '', '', 0);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'SD1', 'Strategisch doel', 'Bewoners blijven langer lichamelijk vitaal', 'Bewoners behouden zo lang mogelijk hun lichamelijke zelfredzaamheid en mobiliteit, met minder functieverlies en minder valincidenten.', 'Missie', 'Gemiddelde ADL-zelfredzaamheidsscore bewoners', '', '', 1);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'SD2', 'Strategisch doel', 'Bewoners blijven langer geestelijk actief en sociaal verbonden', 'Bewoners blijven cognitief actief en ervaren minder eenzaamheid, door sociale en geestelijk uitdagende activiteiten.', 'Missie', 'Gemiddelde welzijns-/eenzaamheidsscore bewoners', '', '', 2);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'SB1', 'Strategische benefit', 'Minder valincidenten en functieverlies', 'Door gerichte preventie en beweging lopen bewoners minder risico op vallen en op geleidelijk functieverlies.', 'SD1', '% minder valincidenten t.o.v. vorig jaar', 'Zorg & Welzijn', 'Lichamelijke vitaliteit', 3);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'SB2', 'Strategische benefit', 'Hogere deelname aan beweegactiviteiten', 'Meer bewoners nemen structureel deel aan beweegactiviteiten die passen bij hun mogelijkheden.', 'SD1', '% bewoners dat wekelijks deelneemt aan beweegactiviteiten', 'Zorg & Welzijn', 'Lichamelijke vitaliteit', 4);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'SB3', 'Strategische benefit', 'Minder eenzaamheid en meer sociale interactie', 'Bewoners hebben meer sociale contactmomenten en voelen zich minder eenzaam.', 'SD2', 'Score eenzaamheidsschaal (verkorte UCLA-schaal)', 'Zorg & Welzijn', 'Sociaal & cognitief', 5);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'SB4', 'Strategische benefit', 'Behoud van cognitieve vaardigheden', 'Bewoners behouden langer hun geheugen- en denkvaardigheden door gerichte training en uitdaging.', 'SD2', 'Gemiddelde MMSE-score bewoners', 'Zorg & Welzijn', 'Sociaal & cognitief', 6);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'PB1', 'Programmabaat', 'Beweegprogramma "Actief Blijven"', 'Een samenhangend programma van dagelijks beweegaanbod en valpreventie, gericht op behoud van lichamelijke vitaliteit.', 'SB1 primair; SB2 primair', 'Samengestelde vitaliteitsindex', 'Zorg & Welzijn', 'Lichamelijke vitaliteit', 7);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'PB2', 'Programmabaat', 'Programma "Samen Actief"', 'Een samenhangend programma van sociale, creatieve en cognitieve activiteiten, gericht op verbondenheid en geestelijke vitaliteit.', 'SB3 primair; SB4 primair', 'Samengestelde welzijns-/cognitie-index', 'Zorg & Welzijn', 'Sociaal & cognitief', 8);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'OB1', 'Operationele benefit', 'Dagelijks beweegaanbod beschikbaar voor alle bewoners', 'Elke bewoner heeft toegang tot een passend, dagelijks beweegaanbod, ongeacht mobiliteitsniveau.', 'PB1', '% bewoners met toegang tot dagelijks beweegaanbod', 'Zorg & Welzijn', 'Lichamelijke vitaliteit', 9);
