    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'OB3', 'Operationele benefit', 'Wekelijkse sociale en creatieve activiteiten', 'Er is een vast, aantrekkelijk aanbod van sociale en creatieve activiteiten waaraan bewoners kunnen deelnemen.', 'PB2', '% bewoners dat wekelijks deelneemt aan sociale activiteiten', 'Zorg & Welzijn', 'Sociaal & cognitief', 11);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'OB4', 'Operationele benefit', 'Individuele geheugentraining beschikbaar', 'Bewoners die dat nodig hebben krijgen toegang tot individuele geheugen- en cognitieve training.', 'PB2', '% bewoners met individueel geheugentrainingsaanbod', 'Zorg & Welzijn', 'Sociaal & cognitief', 12);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'C1', 'Capability', 'Beweeg- en fysiotherapiecapaciteit', 'Vermogen om voldoende gekwalificeerde beweeg- en fysiotherapiebegeleiding te organiseren en beschikbaar te stellen.', 'OB1', 'Beschikbare fysiotherapie-/beweegcoachcapaciteit (fte)', 'Zorg & Welzijn', 'Lichamelijke vitaliteit', 13);
    insert into elements (doelenboom_id, code, type, name, description, parent_text, kpi, taakveld, subtaakveld, sort_order) values ((select id from doelenbomen where slug='gezond-ouder'), 'C2', 'Capability', 'Valrisicoscreening en -monitoring', 'Vermogen om valrisico structureel te screenen, monitoren en te vertalen naar preventieve maatregelen.', 'OB2', '% bewoners met tijdig herhaalde valrisicoscreening', 'Zorg & Welzijn', 'Lichamelijke vitaliteit', 14);
